//! Chrome-format CSV proof: 3 rows — one password was generated by
//! lesspass-core for its site/login/master at counter 3 (lowercase+digits,
//! len 12) and must reverse-match; one seals; one has no password and is
//! skipped.
use lesspass_core::{PasswordOptions, PasswordProfile};
use passforge_desktop::db::VaultDb;
use passforge_desktop::import::{import_credentials, parse};
use passforge_desktop::models::{GenerationMode, Settings};
use passforge_desktop::session::SessionState;
use std::sync::{Arc, Mutex};

#[test]
fn chrome_csv_reverse_match_seal_and_skip() {
    let master = "csv-master";
    let site = "bank.example";
    let login = "alice@bank.example";
    // The reverse-matchable row: derive the password lesspass-core would.
    let options = PasswordOptions {
        lowercase: true, uppercase: false, digits: true, symbols: false, length: 12,
    };
    let profile = PasswordProfile {
        site: site.into(), login: login.into(), counter: 3,
        options: options.clone(), salt_fields: vec![], crypto: None,
    };
    let reverse_pw = lesspass_core::render_password(
        &lesspass_core::calc_entropy(&profile, master, &Default::default()),
        &options,
    ).unwrap();

    let csv = format!(
        "name,url,username,password,note\n\
         Bank,https://www.{site}/login,{login},{reverse_pw},\n\
         Old Forum,oldforum.example,bob@forum.example,l3gacy-pw!!,\n\
         Empty Row,empty.example,none@example.com,,\n"
    );
    let parsed = parse(&csv).unwrap();
    assert_eq!(parsed.credentials.len(), 2);
    assert_eq!(parsed.skipped.len(), 1);

    let db = VaultDb::memory().unwrap();
    db.migrate().unwrap();
    let db = Arc::new(Mutex::new(db));
    let session = SessionState::default();
    session.unlock(master.as_bytes().to_vec()).unwrap();
    let settings = Settings { generation: GenerationMode::Serverless, ..Default::default() };
    let report = import_credentials(&db, &session, &settings, parsed).unwrap();

    assert_eq!(report.total, 3);
    assert_eq!(report.reverse_matched, 1);
    assert_eq!(report.sealed, 1);
    assert_eq!(report.skipped_invalid, 1);
    assert_eq!(report.skipped_duplicate, 0);

    // The reverse-matched entry kept counter 3 + the inferred options.
    let entries = db.lock().unwrap().search_entries("").unwrap();
    let bank = entries.iter().find(|e| e.site == "bank.example").unwrap();
    assert_eq!(bank.counter, 3);
    assert!(db.lock().unwrap().get_sealed(&bank.id).unwrap().is_none());
    let forum = entries.iter().find(|e| e.site == "oldforum.example").unwrap();
    assert!(db.lock().unwrap().get_sealed(&forum.id).unwrap().is_some());
}
